mapper.select:
SELECT rule_id, rule_name, metric_key, compare_type, threshold, unit, collect_interval, duration, alarm_level, silence_duration, scope_type, scope_instance_id, enable_status, created_time, updated_time FROM alarm_rule WHERE del_flag = '0'
AND (rule_name LIKE CONCAT('%',#{keyword},'%') OR metric_key LIKE CONCAT('%',#{keyword},'%'))
AND alarm_level = #{alarmLevel} AND enable_status = #{enableStatus}
AND scope_type = '2' AND (
scope_instance_id LIKE CONCAT('%', #{id}, '%')
)
ORDER BY created_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM alarm_rule WHERE del_flag = '0'

    AND (rule_name LIKE CONCAT('%',#{keyword},'%') OR metric_key LIKE CONCAT('%',#{keyword},'%'))

AND alarm_level = #{alarmLevel}
AND enable_status = #{enableStatus}

    AND scope_type = '2'
    AND (

        scope_instance_id LIKE CONCAT('%', #{id}, '%')

    )
